function v5Ensure(s){if(!s)return s;
 if(!s.v5){s.v5=5;s.honey=s.characterMade?Math.max(0,Math.floor(s.money||0)):0;s.storyFlags=s.storyFlags||{};s.v5Quests={};s.v5Events=[];s.v5Builds=[];s.v5Knowledge={};s.v5NPCMoves=[];s.v5DrugHistory={};s.v5ContrabandLog=[];s.v5Claims={};s.v5Buildup=0;s.v5Bedtime=false;}
 s.playerDependency=s.playerDependency||{nic:0,cannabis:0,alcohol:0,stimulant:0,opioid:0};s.playerCravings=s.playerCravings||{};s.treasureHistory=s.treasureHistory||{};s.honey=Math.max(0,Math.floor(s.honey||0));s.trader=s.trader||{stock:{},met:false};s.trader.honey=Math.max(0,Math.floor(s.trader.honey??22));s.trader.stock=s.trader.stock||{};
 s.npcs.forEach(n=>{n.dependency=n.dependency||{nic:0,cannabis:0,alcohol:0,stimulant:0,opioid:0};n.cravings=n.cravings||{};n.honey=Math.max(0,Math.floor(n.honey??(n.id==='moss'?3:1)));n.sentimental=n.sentimental||n.love;n.sobriety=n.sobriety||0;n.knowledge=n.knowledge||{};n.lastUseDay=n.lastUseDay??-999;n.recovery=n.recovery||0;});
 return s;}
