 const rand=(i)=>((i*1664525+1013904223)>>>0)/4294967296;
 for(let layer=0;layer<3;layer++){for(let i=0;i<15;i++){const x=((i*123+layer*94)%1100)-60,y=170+layer*145+(i%3)*16;const sz=110-layer*8;c.fillStyle=['#325d4c','#244c3c','#1b4031'][layer];c.fillRect(x-12,y-56,24,sz+120);c.fillRect(x-75,y-80,150,82);c.fillRect(x-53,y-112,106,42);c.fillRect(x-24,y-128,48,21);c.fillStyle='#714f37';c.fillRect(x-12,y+22,24,160);}}
