 c.fillStyle='#64432d';c.fillRect(375,365,260,84);c.fillStyle='#c79562';c.fillRect(386,372,239,14);c.fillRect(405,448,24,72);c.fillRect(584,448,24,72);for(let i=0;i<8;i++){c.fillStyle=i%2?'#e3be7a':'#c16b55';c.fillRect(385+i*30,311,30,53)}c.fillStyle='#f0daa4';c.fillRect(450,365,150,37);c.fillStyle='#344937';c.font='bold 22px Georgia';c.fillText('LITTLE POST',460,391);
 drawPortraitMini(c,520,437,2.3);drawPortraitMini(c,285,475,1.2);drawPortraitMini(c,711,460,1.4);
