function v5ShowCreator(){v4CreatorIsOpen=true;v4MenuIsOpen=false;v4Screen.classList.add('open');const av=state.avatar||{};v4Screen.innerHTML=`<div class="v5-title"><canvas class="v5-titleCanvas" id="v5TitleCanvas" width="1000" height="620"></canvas><div class="v5-title-shade"></div><section class="v5-createPage"><h2>MAKE YOUR LITTLE BEAR</h2><p class="v5-mp">Eleven months old. Pebble and Fern are your littermates. Your story starts in Mama's Den.</p><div class="v5-createGrid"><canvas id="v5Preview" width="180" height="180" aria-label="Cub appearance preview"></canvas><div class="v5-createFields"><label>YOUR NAME<input id="v5CubName" maxlength="22" placeholder="What is your cub called?" value="${h(av.name==='Little Cub'?'':av.name||'')}"></label><label>GENDER<select id="v5Gender"><option value="Male">Male (he/him)</option><option value="Female">Female (she/her)</option></select></label><label>COAT COLOR<select id="v5Coat"><option value="#aa774b">Cinnamon brown</option><option value="#78503c">Chocolate</option><option value="#b48c60">Honey brown</option><option value="#584739">Dark umber</option><option value="#9b694b">Russet</option></select></label><label>MARKINGS<select id="v5Markings"><option>Cream muzzle</option><option>Pale chest</option><option>Dark paws</option><option>Freckled snout</option></select></label><label>ACCESSORY<select id="v5Accessory"><option>Golden scarf</option><option>Red ribbon</option><option>Blue bandana</option><option>None</option></select></label><label>EYES<select id="v5Eyes"><option>Dark</option><option>Amber</option><option>Brown</option></select></label><label>TEMPERAMENT<select id="v5Temperament"><option>Curious</option><option>Mischievous</option><option>Shy</option><option>Bold</option><option>Gentle</option><option>Evil</option></select></label></div></div><p class="v5-status" id="v5CreateErr" role="status">Your chosen temperament affects first impressions. Evil cubs start with serious grudges.</p><div class="v5-secondary-menu"><button class="v5-button" id="v5Start">START MY STORY</button><button class="v5-button" id="v5Back">BACK TO MAIN MENU</button></div></section></div>`;v5DrawTitle();$('v5Gender').value=av.gender==='Female'?'Female':'Male';$('v5Coat').value=av.coat||'#aa774b';const paint=()=>{const c=$('v5Preview'),q=c.getContext('2d');q.fillStyle='#b4cba7';q.fillRect(0,0,180,180);q.fillStyle='#50775b';q.fillRect(0,145,180,35);const fur=$('v5Coat').value;q.fillStyle=fur;q.fillRect(46,44,88,105);q.fillRect(37,23,26,34);q.fillRect(117,23,26,34);q.fillStyle=$('v5Markings').value==='Dark paws'?'#594335':'#e3c69b';q.fillRect(61,87,58,36);q.fillStyle='#322a25';q.fillRect(67,70,10,11);q.fillRect(103,70,10,11);q.fillRect(85,100,12,8);q.fillStyle=$('v5Accessory').value==='Red ribbon'?'#b86665':$('v5Accessory').value==='Blue bandana'?'#587d95':'#e2be70';if($('v5Accessory').value!=='None')q.fillRect(53,122,74,9);if($('v5Markings').value==='Freckled snout'){q.fillStyle='#835941';for(const x of [65,71,108,115])q.fillRect(x,101,4,3);}};v4Screen.querySelectorAll('select').forEach(el=>el.onchange=paint);paint();$('v5Back').onclick=v5ShowMenu;$('v5Start').onclick=()=>{const name=$('v5CubName').value.trim().replace(/\s+/g,' ');const reserved=new Set([...NPCS.map(n=>n.name.toLowerCase()),'mama','mama bear','moss','the panda','panda trader','wandering trader','foundling','little cub','you']);if(name.length<2||name.length>22||!/^[- 'A-Za-z]{2,22}$/.test(name)){return $('v5CreateErr').textContent='Please use 2–22 letters, spaces, hyphens or apostrophes.';}if(reserved.has(name.toLowerCase()))return $('v5CreateErr').textContent='That name already belongs to someone in Whisperwood. Choose another.';const gender=$('v5Gender').value,identity={name,gender,pronouns:gender==='Male'?'he/him':'she/her',coat:$('v5Coat').value,markings:$('v5Markings').value.toLowerCase(),accessory:$('v5Accessory').value.toLowerCase(),eyes:$('v5Eyes').value.toLowerCase(),temperament:$('v5Temperament').value,ears:'#6c4735'};state=fresh();state.characterMade=true;state.avatar=identity;state.location='den';state.playerPos=origin.den.slice();state.phase=0;state.day=1;state.phaseActs=0;state.mapVisits.den=1;state.tutorial={enabled:true,step:0,completed:false};for(const sibling of state.npcs.filter(n=>['fern','pebble'].includes(n.id)))sibling.location='den';if(identity.temperament==='Evil'){state.npcs.forEach(n=>{n.rel=-6;n.mood='SUSPICIOUS';n.memory.unshift('D1: Already distrusts the cub for their mean reputation.');});state.rep=0;state.mama.suspicion=28;state.mama.trust=32;log('Your evil reputation precedes you. Other cubs are wary.');}log(`${name} woke in the family den with three berries and one very nice stick.`);save();v4Continue();v5ClosePanel();render();notify('Good morning, '+name+'. Walk over to Mama and press E.');};}
