function v5OpenConversation(n){if(!n||n.location!==state.location)return notify('You must meet this cub in person.');const rel=n.rel||0;const flavor=rel<-2?`${n.name} folds their paws and watches you carefully.`:rel>4?`${n.name} seems happy to see you.`:`${n.name} looks up from a little treasure collection.`;openModal(`${n.name} · ${n.age} months`, `<div class="v5DealReason"><b>${h(n.name)}</b> · ${['fern','pebble'].includes(n.id)?'Your littermate':'Woodland cub'}<p>${h(flavor)}</p><p>“${h(n.quote||n.memory?.[0]||'What do you want to talk about?')}”</p></div><div class="v4OptionStack"><button class="v5Choice" id="v5BarterOption">✦ Let's trade treasures</button><button class="v5Choice" id="v5SocialOption">♡ Talk / play / apologize</button><button class="v5Choice" id="v5AskItem">? Ask about a special possession</button></div>`,[{text:'SAY GOODBYE',action:closeModal}]);$('v5BarterOption').onclick=()=>{closeModal();v5OpenPanel('trade');tradeResult(`${n.name}: Tell me what you want. If I refuse, I'll say why.`,false);};$('v5SocialOption').onclick=()=>{closeModal();v5OpenPanel('dialogue')};$('v5AskItem').onclick=()=>{closeModal();talkAction('ask');};}
const v5OldRender=render;render=function(){v5OldRender();if(!state)return;$('v5Loc').textContent=`${WORLD[state.location]?.short||'WHISPERWOOD'} · Day ${state.day} · ${phaseNames[phase()]}`;const r=$('v5Rest');if(r)r.title=state.location==='den'?'Sleep in Mama’s nest':'Return home to sleep';};
