function v5MarketGate(){if(state.location!=='post')return notify('You must be at YOUR own market gate.');openModal('YOUR MARKET GATE',`<p>These are your facilities. Cubs may trade elsewhere freely, but using your stall requires your rules.</p><p><b>Current policy:</b> ${h(state.policy||'free')} · Total fees collected: ${state.fees||0} · Visitors denied: ${state.denials||0}</p><div class="v4OptionStack"><button class="v5Choice" data-v5policy="free">Open access for everyone</button><button class="v5Choice" data-v5policy="berry">Charge a berry or acorn</button><button class="v5Choice" data-v5policy="treasure">Charge a little treasure</button><button class="v5Choice" data-v5policy="friends">Friends and littermates only</button></div>`,[{text:'CLOSE',action:closeModal}]);document.querySelectorAll('[data-v5policy]').forEach(b=>b.onclick=()=>{const policy=b.dataset.v5policy;closeModal();switchPolicy(policy);});}
