 const candidates=[];for(const [box,inv] of [['carried',state.inv],['post hidden',state.hidden],['den hidden',state.hiddenAt?.den||{}],['stored',state.stored]])for(const id of Object.keys(inv||{})){if(V5_DRUGS[id]&&quantity(inv,id)>0)candidates.push({box,inv,id});}
